def smallest_prime_factor_sum_value(n):
    while True:
        original=n;total=0;factor=2
        while factor*factor<=n:
            while n%factor==0:total+=factor;n//=factor
            factor+=1
        if n>1:total+=n
        if total==original:return original
        n=total

